from AlgorithmImports import *
import math


class TwoSlotStrategyAlgorithm(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(self.RSI_PERIOD)

        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        for symbol in self.symbols.values():
            if not data.Bars.ContainsKey(symbol):
                continue

            close = data.Bars[symbol].Close
            previous_close = self.previous_closes.get(symbol)

            if symbol == self.spy:
                self.spy_sma.Update(IndicatorDataPoint(data.Time, close))

            if symbol == self.aapl:
                if previous_close is None:
                    self.aapl_red_streak = 0
                elif close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                self.aapl_rsi.Update(IndicatorDataPoint(data.Time, close))

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            self._store_closes(data)
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        previous_spy_close = self.previous_closes.get(self.spy)
        previous_spy_sma = None
        if self.spy_sma.IsReady and self.spy_sma.Samples > self.SMA_PERIOD:
            previous_spy_sma = self.spy_sma.Window[1].Value

        spy_crosses_below = (
            previous_spy_close is not None
            and previous_spy_sma is not None
            and previous_spy_close >= previous_spy_sma
            and spy_close < self.spy_sma.Current.Value
        )

        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        spy_crosses_above = (
            previous_spy_close is not None
            and previous_spy_sma is not None
            and previous_spy_close <= previous_spy_sma
            and spy_close > self.spy_sma.Current.Value
        )

        if self.strategy_a_lot == 0 and spy_crosses_above:
            quantity = math.floor((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if (
            self.strategy_b_lot == 0
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = math.floor(20_000 / aapl_close)
            if quantity > 0:
                self.MarketOrder(self.aapl, quantity)
                self.strategy_b_lot = quantity

        self._store_closes(data)

    def _store_closes(self, data: Slice):
        for symbol in self.symbols.values():
            if data.Bars.ContainsKey(symbol):
                self.previous_closes[symbol] = data.Bars[symbol].Close

