        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, 20, Resolution.DAILY)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY)

        self.previous_close = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if not data.bars.contains_key(symbol):
                return
            bars[ticker] = data.bars[symbol]

        spy_close = bars["SPY"].close
        aapl_close = bars["AAPL"].close

        if "AAPL" in self.previous_close:
            if aapl_close < self.previous_close["AAPL"]:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        spy_crosses_above = (
            self.previous_spy_sma is not None
            and "SPY" in self.previous_close
            and self.previous_close["SPY"] <= self.previous_spy_sma
            and spy_close > self.spy_sma.current.value
        )
        spy_crosses_below = (
            self.previous_spy_sma is not None
            and "SPY" in self.previous_close
            and self.previous_close["SPY"] >= self.previous_spy_sma
            and spy_close < self.spy_sma.current.value
        )

        fully_formed = (
            self.spy_sma.is_ready
            and self.aapl_rsi.is_ready
            and "SPY" in self.previous_close
            and "AAPL" in self.previous_close
            and self.previous_spy_sma is not None
        )

        if fully_formed:
            if self.strategy_a_shares > 0 and spy_crosses_below:
                self.market_order(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if self.strategy_b_shares > 0 and self.aapl_rsi.current.value > 60:
                self.market_order(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if self.strategy_a_shares == 0 and spy_crosses_above:
                shares = int((self.portfolio.total_portfolio_value * 0.40) / spy_close)
                if shares > 0:
                    self.market_order(self.spy, shares)
                    self.strategy_a_shares = shares

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                if self.portfolio.cash >= 20_000:
                    shares = int(20_000 / aapl_close)
                    if shares > 0:
                        self.market_order(self.aapl, shares)
                        self.strategy_b_shares = shares

        for ticker, bar in bars.items():
            self.previous_close[ticker] = bar.close

        self.previous_spy_sma = self.spy_sma.current.value

