from AlgorithmImports import *


class IndependentStrategiesAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = [
            self.AddEquity("SPY", Resolution.Daily).Symbol,
            self.AddEquity("AAPL", Resolution.Daily).Symbol,
            self.AddEquity("IBM", Resolution.Daily).Symbol,
            self.AddEquity("BAC", Resolution.Daily).Symbol,
            self.AddEquity("AIG", Resolution.Daily).Symbol
        ]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.spy_sma = SimpleMovingAverage(50)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_last_close = None
        self.spy_last_sma = None
        self.aapl_last_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending_order_id = None
        self.strategy_b_pending_order_id = None

    def OnData(self, data: Slice):
        spy_crossed_above = False
        spy_crossed_below = False

        if data.Bars.ContainsKey(self.spy):
            spy_close = float(data.Bars[self.spy].Close)
            prior_close = self.spy_last_close
            prior_sma = self.spy_last_sma

            self.spy_sma.Update(data.Bars[self.spy].EndTime, spy_close)

            if self.spy_sma.IsReady:
                current_sma = float(self.spy_sma.Current.Value)

                if prior_close is not None and prior_sma is not None:
                    spy_crossed_above = (
                        prior_close <= prior_sma and spy_close > current_sma
                    )
                    spy_crossed_below = (
                        prior_close >= prior_sma and spy_close < current_sma
                    )

                self.spy_last_sma = current_sma

            self.spy_last_close = spy_close

        if data.Bars.ContainsKey(self.aapl):
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.aapl_last_close is not None:
                if aapl_close < self.aapl_last_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(data.Bars[self.aapl].EndTime, aapl_close)
            self.aapl_last_close = aapl_close

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if (
            not self.spy_sma.IsReady
            or self.spy_last_sma is None
            or not self.aapl_rsi.IsReady
        ):
            return

        aapl_rsi_value = float(self.aapl_rsi.Current.Value)

        # Sells before buys.
        if (
            self.strategy_a_lot > 0
            and self.strategy_a_pending_order_id is None
            and spy_crossed_below
        ):
            ticket = self.MarketOrder(self.spy, -self.strategy_a_lot)
            if ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_a_pending_order_id = ticket.OrderId

        if (
            self.strategy_b_lot > 0
            and self.strategy_b_pending_order_id is None
            and aapl_rsi_value > 60
        ):
            ticket = self.MarketOrder(self.aapl, -self.strategy_b_lot)
            if ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.strategy_b_pending_order_id = ticket.OrderId

        if (
            self.strategy_a_lot == 0
            and self.strategy_a_pending_order_id is None
            and spy_crossed_above
        ):
            spy_close = float(data.Bars[self.spy].Close)
            quantity = int(
                float(self.Portfolio.TotalPortfolioValue) * 0.40 / spy_close
            )

            if quantity > 0:
                ticket = self.MarketOrder(self.spy, quantity)
                if ticket.Status not in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.strategy_a_pending_order_id = ticket.OrderId

        if (
            self.strategy_b_lot == 0
            and self.strategy_b_pending_order_id is None
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.CashBook["USD"].Amount) >= 20_000
        ):
            aapl_close = float(data.Bars[self.aapl].Close)
            quantity = int(20_000 / aapl_close)

            if quantity > 0:
                ticket = self.MarketOrder(self.aapl, quantity)
                if ticket.Status not in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.strategy_b_pending_order_id = ticket.OrderId

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if orderEvent.Symbol == self.spy:
                self.strategy_a_lot += int(orderEvent.FillQuantity)
            elif orderEvent.Symbol == self.aapl:
                self.strategy_b_lot += int(orderEvent.FillQuantity)

        if (
            self.strategy_a_pending_order_id is not None
            and orderEvent.OrderId == self.strategy_a_pending_order_id
            and orderEvent.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.strategy_a_pending_order_id = None

        if (
            self.strategy_b_pending_order_id is not None
            and orderEvent.OrderId == self.strategy_b_pending_order_id
            and orderEvent.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.strategy_b_pending_order_id = None

