            self.spy_sma.Update(bar.EndTime, bar.Close)

        if symbol == self.aapl:
            self.aapl_rsi.Update(bar.EndTime, bar.Close)

            if prior_close is not None and bar.Close < prior_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

    def _requirements_ready(self):
        return (
            self.spy_sma.Samples >= self.SMA_PERIOD + 1
            and self.aapl_rsi.IsReady
            and self.previous_close[self.spy] is not None
            and self.previous_close[self.aapl] is not None
        )

    def _spy_crosses_above_sma(self, current_close):
