class IndependentSlotsAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, Market.USA).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, Market.USA).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, Market.USA).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, Market.USA).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, Market.USA).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.spy_closes = deque(maxlen=101)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None
        self.aapl_rsi_ready = False

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        if self._has_actual_bar(data, self.spy):
            self.spy_closes.appendleft(self._decimal(data.Bars[self.spy].Close))

        if self._has_actual_bar(data, self.aapl):
            self._update_aapl_state(self._decimal(data.Bars[self.aapl].Close))

        if self.IsWarmingUp:
            return

        if not all(self._has_actual_bar(data, symbol) for symbol in self.symbols):
            return

        spy_close = self._decimal(data.Bars[self.spy].Close)
        aapl_close = self._decimal(data.Bars[self.aapl].Close)

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and self._spy_crossed_below_sma():
            self.MarketOrder(self.spy, -self.strategy_a_lot, tag="Strategy A sell")
            self.strategy_a_lot = 0

        if (self.strategy_b_lot > 0 and self.aapl_rsi_ready
                and self.aapl_rsi > 60):
            self.MarketOrder(self.aapl, -self.strategy_b_lot, tag="Strategy B sell")
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and self._spy_crossed_above_sma():
            portfolio_value = self._decimal(self.Portfolio.TotalPortfolioValue)
            shares = int((portfolio_value * Decimal("0.40")) / spy_close)

            if shares > 0:
                self.MarketOrder(self.spy, shares, tag="Strategy A buy")
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            purchase_amount = Decimal("20000")
            available_cash = self._decimal(self.Portfolio.Cash)

            if available_cash >= purchase_amount:
                shares = int(purchase_amount / aapl_close)

                if shares > 0:
                    self.MarketOrder(self.aapl, shares, tag="Strategy B buy")
                    self.strategy_b_lot = shares

    def OnSplits(self, splits: Splits):
        for split in splits.Values:
            if split.Type != SplitType.Occurred:
                continue

            factor = self._decimal(split.SplitFactor)
            if factor <= 0:
                continue

            if split.Symbol == self.spy and self.strategy_a_lot > 0:
                self.strategy_a_lot = int(
                    (Decimal(self.strategy_a_lot) / factor).to_integral_value(
                        rounding=ROUND_HALF_UP
                    )
                )

            if split.Symbol == self.aapl and self.strategy_b_lot > 0:
                self.strategy_b_lot = int(
                    (Decimal(self.strategy_b_lot) / factor).to_integral_value(
                        rounding=ROUND_HALF_UP
                    )
                )

    def _has_actual_bar(self, data: Slice, symbol: Symbol) -> bool:
        return data.Bars.ContainsKey(symbol) and not data.Bars[symbol].IsFillForward

    def _spy_crossed_above_sma(self) -> bool:
        if len(self.spy_closes) < 101:
            return False

        prices = list(self.spy_closes)
        today_sma = sum(prices[:100]) / Decimal("100")
        yesterday_sma = sum(prices[1:101]) / Decimal("100")

        return prices[1] <= yesterday_sma and prices[0] > today_sma

    def _spy_crossed_below_sma(self) -> bool:
        if len(self.spy_closes) < 101:
            return False

        prices = list(self.spy_closes)
        today_sma = sum(prices[:100]) / Decimal("100")
        yesterday_sma = sum(prices[1:101]) / Decimal("100")

        return prices[1] >= yesterday_sma and prices[0] < today_sma

    def _update_aapl_state(self, close: Decimal) -> None:
        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            change = float(close - self.aapl_previous_close)
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if not self.aapl_rsi_ready:
                self.rsi_seed_gains.append(gain)
                self.rsi_seed_losses.append(loss)

                if len(self.rsi_seed_gains) == 14:
                    self.rsi_average_gain = sum(self.rsi_seed_gains) / 14.0
                    self.rsi_average_loss = sum(self.rsi_seed_losses) / 14.0
                    self.aapl_rsi = self._calculate_rsi()
                    self.aapl_rsi_ready = True
            else:
                self.rsi_average_gain = (
                    (self.rsi_average_gain * 13.0 + gain) / 14.0
                )
                self.rsi_average_loss = (
                    (self.rsi_average_loss * 13.0 + loss) / 14.0
                )
                self.aapl_rsi = self._calculate_rsi()

        self.aapl_previous_close = close

    def _calculate_rsi(self) -> float:
        if self.rsi_average_loss == 0:
            return 100.0
        if self.rsi_average_gain == 0:
            return 0.0

        relative_strength = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))

    def _decimal(self, value) -> Decimal:
        return Decimal(str(value))

