                shares = int(20_000 / self.Securities[self.aapl].Price)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

    def _update_spy_state(self, bar):
        self.spy_previous_close = self.spy_current_close
        self.spy_previous_sma = self.spy_current_sma
        self.spy_current_close = bar.Close

        self.spy_closes.append(bar.Close)
        if len(self.spy_closes) > 100:
            self.spy_closes.pop(0)

        if len(self.spy_closes) == 100:
            self.spy_current_sma = sum(self.spy_closes) / 100
        else:
            self.spy_current_sma = None

    def _update_aapl_state(self, bar):
        if self.aapl_previous_close is None:
            self.aapl_red_streak = 0
        elif bar.Close < self.aapl_previous_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        self.aapl_previous_close = bar.Close
        self.aapl_rsi.Update(bar.EndTime, bar.Close)

    def _all_required_history_is_ready(self):
        return (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.spy_current_sma is not None
            and self.aapl_rsi.IsReady
        )
