        if strategy is None:
            return

        if orderEvent.FillQuantity != 0:
            self.lots[strategy] += int(orderEvent.FillQuantity)
            if self.lots[strategy] < 0:
                self.lots[strategy] = 0

        if orderEvent.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending[strategy] = False

    def _rules_ready(self):
        return (
            self.spy_sma.IsReady
            and self.spy_close_history.IsReady
            and self.spy_ma_history.IsReady
            and self.aapl_close_history.IsReady
            and self.aapl_rsi.IsReady
        )

    def _submit_order(self, strategy, symbol, quantity):
        if quantity == 0:
            return

        self.pending[strategy] = True
        ticket = self.MarketOrder(symbol, quantity)

        if ticket is None or ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending[strategy] = False

