from AlgorithmImports import *


class PrivateLotStrategiesAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self._symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self._spy = self._symbols["SPY"]
        self._aapl = self._symbols["AAPL"]

        self._spy_sma = SimpleMovingAverage(100)
        self._aapl_rsi = RelativeStrengthIndex(14)

        self._spy_previous_close = None
        self._spy_previous_sma = None
        self._aapl_previous_close = None
        self._aapl_red_streak = 0
        self._aapl_bar_count = 0

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

        self._strategy_a_pending = False
        self._strategy_b_pending = False
        self._order_owners = {}

    def OnData(self, data: Slice):
        self._update_market_state(data)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self._symbols.values()):
            return

        if not self._market_state_is_ready():
            return

        spy_bar = data.Bars[self._spy]
        aapl_bar = data.Bars[self._aapl]

        # Sells are evaluated before buys.
        if not self._strategy_a_pending and self._strategy_a_lot > 0:
            if (self._spy_previous_close <= self._spy_previous_sma and
                    spy_bar.Close < self._spy_sma.Current.Value):
                self._submit_order(
                    self._spy,
                    -self._strategy_a_lot,
                    "A",
                    "Strategy A liquidation"
                )

        if not self._strategy_b_pending and self._strategy_b_lot > 0:
            if self._aapl_rsi.Current.Value > 60:
                self._submit_order(
                    self._aapl,
                    -self._strategy_b_lot,
                    "B",
                    "Strategy B liquidation"
                )

        if not self._strategy_a_pending and self._strategy_a_lot == 0:
            if (self._spy_previous_close <= self._spy_previous_sma and
                    spy_bar.Close > self._spy_sma.Current.Value):
                quantity = int(
                    (self.Portfolio.TotalPortfolioValue * 0.40) / spy_bar.Close
                )
                if quantity > 0:
                    self._submit_order(
                        self._spy,
                        quantity,
                        "A",
                        "Strategy A entry"
                    )

        if not self._strategy_b_pending and self._strategy_b_lot == 0:
            if self._aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 / aapl_bar.Close)
                if quantity > 0:
                    self._submit_order(
                        self._aapl,
                        quantity,
                        "B",
                        "Strategy B entry"
                    )

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.OrderId not in self._order_owners:
            return

        strategy = self._order_owners[orderEvent.OrderId]

        if orderEvent.Status == OrderStatus.PartiallyFilled:
            self._apply_fill(strategy, orderEvent.FillQuantity)

        elif orderEvent.Status == OrderStatus.Filled:
            self._apply_fill(strategy, orderEvent.FillQuantity)
            self._clear_pending(strategy)
            del self._order_owners[orderEvent.OrderId]

        elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
            self._clear_pending(strategy)
            del self._order_owners[orderEvent.OrderId]

    def _update_market_state(self, data):
        if data.Bars.ContainsKey(self._spy):
            spy_bar = data.Bars[self._spy]

            prior_sma = (
                self._spy_sma.Current.Value
                if self._spy_sma.IsReady
                else None
            )

            self._spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            self._spy_previous_sma = prior_sma
            self._spy_previous_close = spy_bar.Close

        if data.Bars.ContainsKey(self._aapl):
            aapl_bar = data.Bars[self._aapl]

            if self._aapl_previous_close is not None:
                if aapl_bar.Close < self._aapl_previous_close:
                    self._aapl_red_streak += 1
                else:
                    self._aapl_red_streak = 0

            self._aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self._aapl_previous_close = aapl_bar.Close
            self._aapl_bar_count += 1

    def _market_state_is_ready(self):
        return (
            self._spy_sma.IsReady and
            self._aapl_rsi.IsReady and
            self._spy_previous_close is not None and
            self._spy_previous_sma is not None and
            self._aapl_bar_count >= 4
        )

    def _submit_order(self, symbol, quantity, strategy, tag):
        ticket = self.MarketOrder(symbol, quantity, True, tag)
        if ticket is None:
            return

        self._order_owners[ticket.OrderId] = strategy

        if strategy == "A":
            self._strategy_a_pending = True
        else:
            self._strategy_b_pending = True

    def _apply_fill(self, strategy, fill_quantity):
        if strategy == "A":
            self._strategy_a_lot += fill_quantity
            if self._strategy_a_lot <= 0:
                self._strategy_a_lot = 0
        else:
            self._strategy_b_lot += fill_quantity
            if self._strategy_b_lot <= 0:
                self._strategy_b_lot = 0

    def _clear_pending(self, strategy):
        if strategy == "A":
            self._strategy_a_pending = False
        else:
            self._strategy_b_pending = False

